import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"المبادئ الأساسية للارتداد الزمني","description":"","frontmatter":{},"headers":[],"relativePath":"ar/82-时间回溯基本原则.md","filePath":"ar/82-时间回溯基本原则.md"}'),o={name:"ar/82-时间回溯基本原则.md"};function l(i,t,h,n,p,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="المبادئ-الأساسية-للارتداد-الزمني" tabindex="-1">المبادئ الأساسية للارتداد الزمني <a class="header-anchor" href="#المبادئ-الأساسية-للارتداد-الزمني" aria-label="Permalink to &quot;المبادئ الأساسية للارتداد الزمني&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>82</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>الارتداد الزمني، الملاحظة أولاً ثم التدخل، استقرار الخط الزمني، حفظ السببية، تثبيت المرساة</td></tr></tbody></table><h2 id="أولاً-تعريف-الارتداد-الزمني-وجوهره" tabindex="-1">أولاً: تعريف الارتداد الزمني وجوهره <a class="header-anchor" href="#أولاً-تعريف-الارتداد-الزمني-وجوهره" aria-label="Permalink to &quot;أولاً: تعريف الارتداد الزمني وجوهره&quot;">​</a></h2><p>الارتداد الزمني هو سلوك إعادة الوعي أو المعلومات أو المادة إلى عقدة زمنية ماضية، عبر قدرة التشغيل على بُعد الزمن في شبكة قوانين المرساة. في إطار قوانين كون هنغ يوان، الزمن ليس تدفقاً خطياً أحادي الاتجاه لا رجعة فيه، بل بُعد قابل للتشغيل في شبكة القوانين. ومع ذلك، فإن التشغيل على بُعد الزمن يحمل مخاطر بالغة الارتفاع وقيوداً صارمة؛ فقد يسبب أي سلوك ارتداد زمني اضطراباً في السلاسل السببية، وانقساماً في الخطوط الزمنية، وحتى تموجات قوانين على مقياس الكون.</p><p>جوهر الارتداد الزمني هو «إنشاء قناة ارتداد على بُعد الزمن في شبكة القوانين، تسمح لمعلومات أو طاقة محددة بالانتشار عكسياً على طول القناة». تستهلك هذه العملية كمية هائلة من طاقة المرساة، وكلما كان الارتداد أقدم وكان المحتوى المرتد أكثر تعقيداً، زاد استهلاك الطاقة نمواً أسياً. حالياً، تدعم القدرة التقنية لكون هنغ يوان الارتداد على مستوى الوعي والمعلومات فقط، أما الارتداد الكامل على مستوى المادة فلا يزال في مرحلة البحث النظري.</p><p>يجب التأكيد بوجه خاص على أن الارتداد الزمني لا يعادل «السفر عبر الزمن». فالمرتد لا يدخل الماضي بصورة مادية كاملة، بل يصل إلى العقدة الزمنية المستهدفة على هيئة إسقاط وعي أو حزمة معلومات. وجود المرتد في الفترة الماضية «شبه شفاف» — يمكن رصده، لكن قدرة التفاعل الفيزيائي محدودة بصرامة. هذا التصميم بحد ذاته جزء من آلية أمان الارتداد الزمني.</p><h2 id="ثانياً-المبادئ-الأساسية-السبعة-للارتداد-الزمني" tabindex="-1">ثانياً: المبادئ الأساسية السبعة للارتداد الزمني <a class="header-anchor" href="#ثانياً-المبادئ-الأساسية-السبعة-للارتداد-الزمني" aria-label="Permalink to &quot;ثانياً: المبادئ الأساسية السبعة للارتداد الزمني&quot;">​</a></h2><p>تتبع عمليات الارتداد الزمني في كون هنغ يوان المبادئ الأساسية السبعة التالية، التي أرساها المجلس التشريعي للمرساة في صورة قرارات خاصة، وتتمتع بقوة قانونية تلي الدستور مباشرة:</p><table tabindex="0"><thead><tr><th>رقم المبدأ</th><th>اسم المبدأ</th><th>المضمون الجوهري</th></tr></thead><tbody><tr><td>المبدأ الأول</td><td>الملاحظة أولاً ثم التدخل المحدود</td><td>يجب على أي ارتداد إكمال مرحلة الملاحظة الخالصة أولاً؛ وبعد التأكد من عدم وجود مخاطر كبرى فقط يمكن إجراء تدخل محدود</td></tr><tr><td>المبدأ الثاني</td><td>حفظ السببية</td><td>يجب ألا يغير الارتداد السلاسل السببية الجوهرية التي حدثت؛ والانحرافات السببية الناتجة عن الارتداد يجب تصحيحها بعد انتهاء الارتداد</td></tr><tr><td>المبدأ الثالث</td><td>تثبيت المرساة</td><td>يجب أن تتخذ جميع عمليات الارتداد مرساة مستقرة أصلاً للإحداثيات الزمنية؛ ويُحظر الارتداد الأعمى دون مرساة</td></tr><tr><td>المبدأ الرابع</td><td>التأثير الأدنى</td><td>يجب أن تتبع جميع السلوكيات في عملية الارتداد مبدأ التأثير الأدنى، وتقليل اضطراب الخط الزمني الماضي قدر الإمكان</td></tr><tr><td>المبدأ الخامس</td><td>قابلية التتبع</td><td>يجب على كل ارتداد تسجيل سجلات التشغيل تسجيلاً كاملاً، بما فيها هوية المرتد، والزمن المستهدف، والمحتوى المرصود، وسلوكيات التدخل، وتقييم الانحرافات السببية</td></tr><tr><td>المبدأ السادس</td><td>حظر المفارقات</td><td>يُحظر بصرامة أي عملية قد تؤدي إلى مفارقات زمنية، بما في ذلك على سبيل المثال لا الحصر مفارقة قتل الجد، ومفارقة المعلومات، والمفارقة الوجودية</td></tr><tr><td>المبدأ السابع</td><td>التدقيق اللاحق</td><td>يجب بعد انتهاء الارتداد أن تجري لجنة تدقيق قوانين الزمن المستقلة تدقيقاً لاحقاً، للتأكد من عدم حدوث اضطراب لا يمكن ضبطه في الخط الزمني</td></tr></tbody></table><p>من بين المبادئ السبعة، «الملاحظة أولاً ثم التدخل المحدود» هو المبدأ التشغيلي الأكثر جوهرية، وتنفرج المبادئ الستة الأخرى حول هذا الجوهر. المواصفات التشغيلية التفصيلية لهذا المبدأ واردة في الوثيقة 83 «معايير الملاحظة أولاً ثم التدخل المحدود».</p><h2 id="ثالثاً-الإدارة-التصنيفية-للارتداد-الزمني" tabindex="-1">ثالثاً: الإدارة التصنيفية للارتداد الزمني <a class="header-anchor" href="#ثالثاً-الإدارة-التصنيفية-للارتداد-الزمني" aria-label="Permalink to &quot;ثالثاً: الإدارة التصنيفية للارتداد الزمني&quot;">​</a></h2><p>وفقاً للمدى الزمني ودرجة التدخل في الارتداد، تُقسم عمليات الارتداد الزمني إلى ثلاثة مستويات إدارية:</p><ol><li><p><strong>ارتداد من المستوى الأول (ملاحظة قريبة)</strong>: ألا يتجاوز المدى الزمني للارتداد 100 عام من الزمن القياسي للبُعد الخاص، وأن يكون ملاحظة خالصة فقط دون أي تدخل. يوافق عليه إدارة الأبعاد، مع حضور ما لا يقل عن اثنين من مفتشي قوانين الزمن للإشراف على سير العملية.</p></li><li><p><strong>ارتداد من المستوى الثاني (ملاحظة بعيدة)</strong>: أن يتجاوز المدى الزمني للارتداد 100 عام دون أن يتجاوز 10000 عام، أو أن يتطلب الارتداد تدخلاً خفيفاً للغاية (كنقل معلومة واحدة). يجب أن توافق عليه لجنة قوانين الزمن التابعة للمجلس التشريعي للمرساة، مع وضع خطة طوارئ تفصيلية للانحرافات السببية.</p></li><li><p><strong>ارتداد من المستوى الثالث (تدخل عميق)</strong>: أن يتجاوز المدى الزمني للارتداد 10000 عام، أو أن يتطلب الارتداد تدخلاً جوهرياً. يجب أن توافق عليه الجلسة العامة للمجلس التشريعي للمرساة بأغلبية تزيد على الثلثين، وأن يخضع لمراجعة دستورية من محكمة التكافل، للتأكد من أن سلوك التدخل يتوافق مع المبادئ الجوهرية للدستور التكافلي.</p></li></ol><p>يُحظر استخدام الارتداد الزمني من أي مستوى للأغراض التالية: نيل منافع خاصة لأفراد أو جماعات صغيرة، وتغيير مصائر الشخصيات التاريخية إرضاءً للرغبات الشخصية، والتلاعب بالمسار الطبيعي لتطور الحضارة، وأي شكل من أشكال عمليات «تحريفية التاريخ».</p><h2 id="رابعاً-القيود-الطاقية-والتقنية-للارتداد-الزمني" tabindex="-1">رابعاً: القيود الطاقية والتقنية للارتداد الزمني <a class="header-anchor" href="#رابعاً-القيود-الطاقية-والتقنية-للارتداد-الزمني" aria-label="Permalink to &quot;رابعاً: القيود الطاقية والتقنية للارتداد الزمني&quot;">​</a></h2><p>استهلاك الطاقة للارتداد الزمني بالغ الضخامة. فمثلاً، في ارتداد إسقاط الوعي، تتطلب الطاقة اللازمة للارتداد لسنة واحدة نحو 10000 وحدة طاقة قياسية؛ ولارتداد 100 عام، نحو مليون وحدة طاقة قياسية؛ ولارتداد 10000 عام، نحو 10 مليارات وحدة طاقة قياسية. العلاقة بين استهلاك الطاقة والمدى الزمني للارتداد خطية لوغاريتمية تقريباً، لكن تحدث قمم طاقية عند عبور العقد التاريخية الكبرى — لأن كثافة السلاسل السببية عند العقد التاريخية الكبرى عالية للغاية، وتتطلب عمليات الارتداد التغلب على قصور سببي أكبر.</p><p>على المستوى التقني، يتطلب الارتداد الزمني عمل «جهاز تثبيت قوانين الزمن» و«مصفوفة نقل إسقاطات الوعي» بتناسق. الأول مسؤول عن إنشاء إحداثية زمنية مستقرة عند العقدة الزمنية المستهدفة؛ والثاني مسؤول عن إيصال إسقاط وعي المرتد بأمان والحفاظ على وجوده في الفترة الماضية. يجب أن تجتاز جميع أجهزة الارتداد شهادة الأمان من لجنة الرقابة للمرساة؛ ويُحظر استخدام أجهزة ذاتية الصنع غير معتمدة في عمليات الارتداد.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>الارتداد الزمني من أقوى قدرات التشغيل على القوانين وأخطرها في كون هنغ يوان. تشكل المبادئ الأساسية السبعة ونظام الإدارة التصنيفية معاً إطار أمان الارتداد الزمني، وروحه الجوهرية هي «إجلال السببية، والتحرك بحذر». الاستخدامات المشروعة للارتداد الزمني مقصورة على البحث الأثري، واستعادة الحقيقة التاريخية، والإنذار المبكر بأزمات مستوى الانقراض؛ وأي استخدام يتجاوز هذا النطاق سيُعد تدنيساً لقوانين الكون.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>83-先观测后有限干涉准则 (معايير الملاحظة أولاً ثم التدخل المحدود)</li><li>89-时间悖论防控机制 (آلية الوقاية من مفارقات الزمن وضبطها)</li><li>84-考古协议总纲 (البروتوكول العام لعلم الآثار)</li></ul>',21)])])}const b=a(o,[["render",l]]);export{c as __pageData,b as default};
